CREATE FUNCTION public.biz_report_period_matches(_user uuid,_pk text,_year integer,_period integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM generate_series(public.biz_period_start_date(_pk,_year,_period)::timestamp,public.biz_period_end_date(_pk,_year,_period)::timestamp,interval '1 day') day_ WHERE public.biz_department_at(_user,day_::date) IS NOT NULL AND public.biz_report_cycle_of(_user,day_::date)<>_pk) AND public.biz_report_cycle_of(_user,public.biz_period_start_date(_pk,_year,_period))=_pk $$;
REVOKE ALL ON FUNCTION public.biz_report_period_matches(uuid,text,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_report_period_matches(uuid,text,integer,integer) TO authenticated;
DO $patch$
DECLARE f text; marker text;
BEGIN
 SELECT pg_get_functiondef('private.biz_report_obligations(integer,text,integer)'::regprocedure) INTO f;f:=replace(f,'public.biz_report_cycle_of(m.user_id,m.starts)=m.pk','public.biz_report_period_matches(m.user_id,m.pk,m.y,m.p)');EXECUTE f;
 SELECT pg_get_functiondef('public.biz_documents_read(text,text,integer,integer)'::regprocedure) INTO f;f:=replace(f,'public.biz_report_cycle_of(p.id,public.biz_period_start_date(_period_kind,_year,_period))=_period_kind','public.biz_report_period_matches(p.id,_period_kind,_year,_period)');EXECUTE f;
 SELECT pg_get_functiondef('public.biz_document_start(text,text,integer,integer,text)'::regprocedure) INTO f;marker:='IF d.id IS NULL AND _kind=''report'' THEN';IF position(marker IN f)=0 THEN RAISE EXCEPTION 'Start shape changed';END IF;f:=replace(f,marker,marker||' IF NOT public.biz_report_period_matches(auth.uid(),_period_kind,_year,_period) THEN RAISE EXCEPTION ''Kỳ xem giao thời điểm đổi chu kỳ; chỉ nộp kỳ nguồn được giao, không tạo nghĩa vụ trùng.''; END IF;');EXECUTE f;
 SELECT pg_get_functiondef('public.biz_my_work(text)'::regprocedure) INTO f;marker:='phase:=public.biz_any_phase(_kind,rec.pk,rec.y,rec.p,v_now);';IF position(marker IN f)=0 THEN RAISE EXCEPTION 'Work shape changed';END IF;f:=replace(f,marker,'IF _kind=''report'' AND NOT public.biz_report_period_matches(auth.uid(),rec.pk,rec.y,rec.p) AND NOT EXISTS(SELECT 1 FROM public.biz_documents WHERE user_id=auth.uid() AND kind=''report'' AND period_kind=rec.pk AND year=rec.y AND period=rec.p) THEN CONTINUE; END IF; '||marker);EXECUTE f;
END $patch$;